    @Override public void onCreate(Bundle saved){
        super.onCreate(saved);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
        if(android.os.Build.VERSION.SDK_INT>=29)getWindow().setNavigationBarContrastEnforced(false);
        store=new ProjectStore(this);try{state=store.read();}catch(IllegalStateException error){state=MusicData.defaults();recovery=true;}
        player=new SynthPlayer(this);
        googleDraft=getPreferences(0).getString("googleDraft",googleDraft);googleContext=getPreferences(0).getBoolean("googleContext",true);
        if(saved!=null){tab=saved.getString("tab","idea");melodyBar=saved.getInt("bar",0);melodyBase=saved.getInt("base",60);builderRoot=saved.getInt("builderRoot",5);builderOctave=saved.getInt("builderOctave",4);builderInversion=saved.getInt("builderInversion",0);builderQuality=saved.getString("builderQuality","minor");sparse=saved.getBoolean("sparse",true);int[] keys=saved.getIntArray("recognition");if(keys!=null)for(int n:keys)recognized.add(n);}
        render();
    }
    @Override protected void onResume(){super.onResume();handler.removeCallbacks(ticker);handler.post(ticker);}
    @Override protected void onPause(){captureQuestion();getPreferences(0).edit().putString("googleDraft",googleDraft).putBoolean("googleContext",googleContext).apply();stopAudio();handler.removeCallbacks(ticker);super.onPause();}
    @Override protected void onDestroy(){handler.removeCallbacks(ticker);fileWorker.shutdown();if(player!=null)player.release();super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("tab",tab);out.putInt("bar",melodyBar);out.putInt("base",melodyBase);out.putInt("builderRoot",builderRoot);out.putInt("builderOctave",builderOctave);out.putInt("builderInversion",builderInversion);out.putString("builderQuality",builderQuality);out.putBoolean("sparse",sparse);out.putIntArray("recognition",recognized.stream().mapToInt(Integer::intValue).toArray());}
