    private void listenScale(){Project p=MusicData.copy(MusicData.defaults().projects.get(0));p.root=project().root;p.scaleId=project().scaleId;p.bpm=90;p.playChords=false;p.playBass=false;p.playMelody=true;p.melody.clear();int i=0;for(int interval:MusicTheory.scale(p.scaleId).intervals){Note n=new Note();n.midi=60+p.root+interval;n.start=i*2;n.length=2;p.melody.add(n);i++;}Note last=new Note();last.midi=72+p.root;last.start=i*2;last.length=3;p.melody.add(last);p.chords.clear();Chord dummy=new Chord();dummy.root=p.root;dummy.beats=(last.start+last.length+3)/4;p.chords.add(dummy);try{playStarted=0;player.play(p,this::updatePlayback);}catch(RuntimeException e){toast(e.getMessage());}}
