    private void renameProject(Project p){LinearLayout f=form();EditText name=input(f,p.name,"Название идеи",120);AlertDialog d=new AlertDialog.Builder(this).setTitle("Название идеи").setView(f).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{String title=name.getText().toString().trim();if(title.isEmpty()){toast("Напиши название.");return;}String old=p.name;long previousUpdated=p.updatedAt;p.name=title;p.updatedAt=Math.max(System.currentTimeMillis(),p.createdAt);if(!persist()){p.name=old;p.updatedAt=previousUpdated;return;}syncUndoMetadata();d.dismiss();rerender();}));d.show();}
    private void newProject(boolean copy){if(state.projects.size()>=200){toast("Можно сохранить до 200 проектов.");return;}Project p=MusicData.copy(copy?project():MusicData.defaults().projects.get(0));p.id=UUID.randomUUID().toString();p.name=copy?"Копия · "+project().name:"Новая идея";if(p.name.length()>120)p.name=p.name.substring(0,120);p.createdAt=p.updatedAt=System.currentTimeMillis();String old=state.currentId;state.projects.add(p);state.currentId=p.id;if(!persist()){state.projects.remove(p);state.currentId=old;return;}stopAudio();undo=null;melodyBar=0;tab="idea";render();renameProject(p);}
    private void deleteProject(Project p){if(state.projects.size()<=1){toast("Оставь хотя бы одну идею. Можно создать новую и удалить эту.");return;}new AlertDialog.Builder(this).setTitle("Удалить идею?").setMessage(p.name).setNegativeButton("Оставить",null).setPositiveButton("Удалить",(d,w)->{stopAudio();int index=state.projects.indexOf(p);String old=state.currentId;state.projects.remove(p);if(p.id.equals(state.currentId))state.currentId=state.projects.get(0).id;if(!persist()){state.projects.add(index,p);state.currentId=old;return;}undo=null;render();}).show();}
